class EventEmitter {
  on(event, listener) { this.events[event].push(listener); }
  emit(event, data) { this.events[event].forEach(l => l(data)); }
}

const emitter = new EventEmitter();
emitter.on("update", data => console.log(data));
emitter.emit("update", { id: 1 });

type Listener<T> = (value: T) => void;

class Subject<T> {
  private listeners = new Set<Listener<T>>();

  subscribe(listener: Listener<T>): () => void {
    this.listeners.add(listener);

    return () => this.listeners.delete(listener);
  }

  next(value: T): void {
    for (const listener of this.listeners) {
      listener(value);
    }
  }
}

const price = new Subject<number>();
const unsubscribe = price.subscribe((p) => console.log("Price", p));

price.next(19.99);
unsubscribe();

import {
  fromEvent,
  map,
  debounceTime,
  distinctUntilChanged,
  switchMap,
} from "rxjs";
import { ajax } from "rxjs/ajax";

const input = document.querySelector("input")!;

fromEvent(input, "input")
  .pipe(
    map((e) => (e.target as HTMLInputElement).value),
    debounceTime(300),
    distinctUntilChanged(),
    switchMap((term) => ajax.getJSON(`/api/search?q=${term}`)),
  )
  .subscribe((results) => render(results));
